const MAP = {
 "backbone": [
  "Browse",
  "Select",
  "Checkout",
  "Pay",
  "Track"
 ],
 "stories": [
  {
   "id": "S1",
   "step": "Browse",
   "title": "List products by category",
   "priority": "Must"
  },
  {
   "id": "S2",
   "step": "Browse",
   "title": "Search by keyword",
   "priority": "Should"
  },
  {
   "id": "S3",
   "step": "Select",
   "title": "Add to cart",
   "priority": "Must"
  },
  {
   "id": "S4",
   "step": "Checkout",
   "title": "Apply coupon",
   "priority": "Should"
  },
  {
   "id": "S5",
   "step": "Checkout",
   "title": "Guest checkout",
   "priority": "Must"
  },
  {
   "id": "S6",
   "step": "Pay",
   "title": "Pay by card",
   "priority": "Must"
  },
  {
   "id": "S7",
   "step": "Track",
   "title": "E-mail order status",
   "priority": "Could"
  },
  {
   "id": "S8",
   "step": "Track",
   "title": "Live courier map",
   "priority": "Could"
  }
 ]
};

var RANK = { 'Must': 0, 'Should': 1, 'Could': 2 };

function skeleton(map) {
  var release1 = [], gaps = [];
  map.backbone.forEach(function (step) {
    var best = null;
    map.stories.forEach(function (s) {
      if (s.step !== step || !Object.prototype.hasOwnProperty.call(RANK, s.priority)) return;
      if (!best || RANK[s.priority] < RANK[best.priority]) best = s;
    });
    if (best) release1.push(best.id); else gaps.push(step);
  });
  return { release1: release1, gaps: gaps };
}
